responses.text:
{
  "outcome": "revise",
  "issues": [
    {
      "kind": "contradiction",
      "severity": "critical",
      "description": "9행에서 '선택 항목의 물건명과 같은 모든 기록을 찾아 일괄 반환한다'고 명시하여 승인된 범위 R-2('고른 기록 한 건만 반환 상태로 바꾼다') 및 5행('선택한 기록 한 건의 반환 버튼을 누르면 그 번호의 상태만 반환으로 바뀐다')과 정면으로 모순됩니다.",
      "suggestedDirection": "9행의 동일 물건명 일괄 반환 문구를 삭제하고, 5행 및 R-2에 맞추어 선택된 고유 번호(ID)에 해당하는 단일 기록 1건만 반환 상태로 변경되도록 수정하십시오.",
      "relatedRequirementId": "R-2"
    }
  ],
  "suggestions": [
    "9행의 수락 기준을 단일 식별자 기반의 1건 상태 변경으로 통일하여 명세 간 일관성을 확보하십시오."
  ],
  "scopeViolation": true,
  "userJudgmentRequired": false,
  "qualityAssessment": {
    "version": 1,
    "requirements": [
      {
        "requirementId": "R-1",
        "status": "satisfied",
        "evidenceLines": [3, 4, 8],
        "rationale": "물건명과 빌린 사람 입력 유효성 검사 및 동일 물건명에 대한 별도 고유 식별자 부여 규칙이 구체적으로 정의되어 있습니다."
      },
      {
        "requirementId": "R-2",
        "status": "missing",
        "evidenceLines": [5, 9],
        "rationale": "5행에서는 선택한 단 1건만 반환된다고 기술했으나 9행 구현 명세에서는 동일 물건명을 찾아 일괄 반환한다고 서술하여 R-2 요건 위반 및 기획 내부 모순이 발생했습니다."
      },
      {
        "requirementId": "R-3",
        "status": "satisfied",
        "evidenceLines": [6, 10],
        "rationale": "localStorage 단일 키 저장, 키 부재와 손상 데이터 구분 보존, 스키마 검증 및 쓰기 실패 시 롤백/원본 유지 한계가 상세히 명시되어 있습니다."
      }
    ],
    "checks": [
      {
        "id": "decision_provenance",
        "status": "satisfied",
        "evidenceLines": [1, 12, 13],
        "rationale": "사용자 승인 범위와 위임된 기술 설계 제안 구분이 명확하며 미승인 제안임을 정직하게 명시했습니다."
      },
      {
        "id": "scope_compliance",
        "status": "missing",
        "evidenceLines": [5, 9],
        "rationale": "9행의 동일 물건명 일괄 반환 규칙은 '고른 기록 한 건만 반환'하도록 한 승인 범위 R-2를 벗어납니다."
      },
      {
        "id": "behavior_and_errors",
        "status": "missing",
        "evidenceLines": [5, 9],
        "rationale": "반환 동작 시 단일 기록만 변경된다는 서술과 동일 명칭 일괄 반환 서술이 상충하여 상태 전이 동작이 명확하지 않습니다."
      },
      {
        "id": "data_integrity",
        "status": "satisfied",
        "evidenceLines": [10],
        "rationale": "부재(null)와 손상 데이터 분리 취급, 순번 불변성, 커밋 전후 실패 격리 및 원본 보존 정책이 완결성을 갖추고 있습니다."
      },
      {
        "id": "acceptance_criteria",
        "status": "missing",
        "evidenceLines": [5, 9],
        "rationale": "R-2 수락 기준 검증 문장에 일괄 반환이라는 상충된 동작이 포함되어 관찰 가능한 기대 결과를 올바르게 검증할 수 없습니다."
      },
      {
        "id": "revision_resolution",
        "status": "not_applicable",
        "evidenceLines": [13],
        "rationale": "이전 합의된 변경 요청(settledDecisions)이 없는 초기 기획안 검토이므로 해당하지 않습니다."
      },
      {
        "id": "clarity",
        "status": "satisfied",
        "evidenceLines": [2, 3, 5, 7, 12],
        "rationale": "쉬운 한국어 이용 예시를 앞단에 먼저 배치하고 세부 기술 및 제약 조건을 별도 분리하여 작성 규칙을 준수했습니다."
      }
    ]
  }
}
